// zip.test.mjs
import { test } from 'node:test';
import assert from 'node:assert/strict';

const ZIP_RE = /^[0-9]{5}(?:-[0-9]{4})?$/;

test('accepts 5-digit ZIP', () => {
  assert.ok(ZIP_RE.test('12345'));
  assert.ok(ZIP_RE.test('02134')); // leading zero
});

test('accepts ZIP+4', () => {
  assert.ok(ZIP_RE.test('12345-6789'));
});

test('rejects malformed input', () => {
  const bad = [
    '', '1234', '123456',
    '12345-', '12345-678', '12345-67890',
    '123456789',            // no hyphen, rejected by the strict pattern
    'abcde', ' 12345', '12345 ',
  ];
  for (const value of bad) {
    assert.ok(!ZIP_RE.test(value), `expected "${value}" to be rejected`);
  }
});
```

